/**
 * CI grep-guard for the `rhythm-*` regression.
 *
 * Background: Card.linear / MetricTile.linear / Hero.linear / Section
 * once used Tailwind classes like `px-rhythm-comfortable`, `py-rhythm-tight`,
 * `mb-rhythm-tight`. Those class names were never generated by the library's
 * Tailwind preset — the config has no matching spacing scale — so they
 * silently no-op'd. Result: MetricTile shipped with `padding: 16px 0px`
 * (zero horizontal), Card was flush, Hero collapsed. Diagnosed live on
 * tr7rfk34 via getComputedStyle.
 *
 * The source fix replaced every `-rhythm-*` occurrence with real Tailwind
 * utilities (`px-6`, `py-2`, `mb-2`, etc.). This test locks that decision
 * in: any future `-rhythm-` class name in library source fails CI. If a
 * real design-token-driven rhythm scale ever lands, extend PRESET_KNOWN
 * with the values the preset actually generates.
 */
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import { describe, it, expect } from "vitest";

const SRC = join(__dirname, "..", "src");
const PRESET_KNOWN = new Set<string>();  // add rhythm-* names when a preset ships them

function walk(dir: string, acc: string[] = []): string[] {
  for (const entry of readdirSync(dir)) {
    const p = join(dir, entry);
    const s = statSync(p);
    if (s.isDirectory()) walk(p, acc);
    else if (/\.(ts|tsx)$/.test(entry)) acc.push(p);
  }
  return acc;
}

describe("no unregistered rhythm-* classes in library source", () => {
  it("every `-rhythm-<name>` in source resolves to a preset-registered name", () => {
    const bad: Array<{ file: string; matches: string[] }> = [];
    for (const file of walk(SRC)) {
      const txt = readFileSync(file, "utf8");
      const matches = txt.match(/[a-z]+-rhythm-[a-z]+/g);
      if (!matches) continue;
      const unregistered = matches.filter((m) => {
        const suffix = m.split("-").slice(2).join("-");  // "px-rhythm-comfortable" → "comfortable"
        return !PRESET_KNOWN.has(suffix);
      });
      if (unregistered.length) bad.push({ file: file.replace(SRC, "src"), matches: unregistered });
    }
    expect(bad, `unregistered rhythm-* classes:\n${JSON.stringify(bad, null, 2)}`).toEqual([]);
  });
});
